from pathlib import Path

path = Path('app/src/main/java/com/clickgo/motorista/MainActivity.java')
text = path.read_text(encoding='utf-8')

def repl(old, new, name):
    global text
    if old not in text:
        raise SystemExit(f'Trecho não encontrado: {name}')
    text = text.replace(old, new, 1)

if 'import android.text.method.PasswordTransformationMethod;' not in text:
    text = text.replace('import android.text.InputType;\n', 'import android.text.InputType;\nimport android.text.method.PasswordTransformationMethod;\n', 1)
if 'import java.util.concurrent.atomic.AtomicBoolean;' not in text:
    text = text.replace('import java.util.concurrent.Executors;\n', 'import java.util.concurrent.Executors;\nimport java.util.concurrent.atomic.AtomicBoolean;\n', 1)

repl('''    private boolean destroyed;\n''','''    private boolean destroyed;\n    private final AtomicBoolean refreshingOperation = new AtomicBoolean(false);\n    private final AtomicBoolean sendingLocation = new AtomicBoolean(false);\n''','flags estabilidade')

old_login = '''    private void showLogin() {\n        LinearLayout body = vertical(BLACK); body.setPadding(dp(24),dp(50),dp(24),dp(30));\n        body.addView(text("CLICK-GO",18,YELLOW,true)); body.addView(space(12));\n        body.addView(text("App Motorista",32,Color.WHITE,true));\n        body.addView(text("Entre para ficar online e receber corridas.",15,GRAY,false)); body.addView(space(26));\n        EditText email = edit("E-mail"), pass = edit("Senha");\n        pass.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);\n        body.addView(email,match(dp(58))); body.addView(space(10)); body.addView(pass,match(dp(58))); body.addView(space(16));\n        Button enter = primary("Entrar"); body.addView(enter,match(dp(58))); body.addView(space(14));\n        body.addView(text("O franqueado da cidade precisa aprovar seu cadastro antes de você ficar online.",13,GRAY,false));\n        enter.setOnClickListener(v -> login(email.getText().toString().trim(), pass.getText().toString()));\n        setContentView(scroll(body,BLACK));\n    }\n'''
new_login = '''    private void showLogin() {\n        stopPolling();\n        stopLocationWatch();\n        releaseMap();\n        LinearLayout body = vertical(BLACK); body.setPadding(dp(24),dp(50),dp(24),dp(30));\n        body.addView(text("CLICK-GO",18,YELLOW,true)); body.addView(space(12));\n        body.addView(text("App Motorista",32,Color.WHITE,true));\n        body.addView(text("Entre para ficar online e receber corridas.",15,GRAY,false)); body.addView(space(26));\n        EditText email = edit("E-mail"), pass = edit("Senha");\n        pass.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_PASSWORD);\n        pass.setTransformationMethod(PasswordTransformationMethod.getInstance());\n        Button eye = darkButton("👁");\n        eye.setContentDescription("Mostrar ou ocultar senha");\n        final boolean[] visible = {false};\n        eye.setOnClickListener(v -> {\n            int pos = pass.getSelectionStart();\n            visible[0] = !visible[0];\n            pass.setTransformationMethod(visible[0] ? null : PasswordTransformationMethod.getInstance());\n            eye.setText(visible[0] ? "🙈" : "👁");\n            pass.setSelection(Math.max(0, Math.min(pos, pass.length())));\n        });\n        LinearLayout passwordRow = horizontal();\n        passwordRow.addView(pass,new LinearLayout.LayoutParams(0,dp(58),1));\n        passwordRow.addView(spaceH(8));\n        passwordRow.addView(eye,new LinearLayout.LayoutParams(dp(58),dp(58)));\n        body.addView(email,match(dp(58))); body.addView(space(10)); body.addView(passwordRow,match(dp(58))); body.addView(space(16));\n        Button enter = primary("Entrar"); body.addView(enter,match(dp(58))); body.addView(space(10));\n        TextView forgot = text("Esqueci minha senha?",15,YELLOW,true); forgot.setGravity(Gravity.CENTER); forgot.setPadding(0,dp(8),0,dp(8)); body.addView(forgot,match(dp(48)));\n        body.addView(space(8));\n        body.addView(text("O franqueado da cidade precisa aprovar seu cadastro antes de você ficar online.",13,GRAY,false));\n        enter.setOnClickListener(v -> login(email.getText().toString().trim(), pass.getText().toString()));\n        forgot.setOnClickListener(v -> showRecovery(email.getText().toString().trim()));\n        setContentView(scroll(body,BLACK));\n    }\n\n    private void showRecovery(String initialEmail) {\n        stopPolling();\n        stopLocationWatch();\n        releaseMap();\n        LinearLayout body = vertical(BLACK); body.setPadding(dp(24),dp(42),dp(24),dp(30));\n        Button back = darkButton("← Voltar"); body.addView(back,new LinearLayout.LayoutParams(dp(110),dp(50)));\n        body.addView(space(22)); body.addView(text("Recuperar acesso",30,Color.WHITE,true)); body.addView(space(8));\n        body.addView(text("Informe o e-mail da sua conta. Enviaremos um link para você criar uma nova senha.",15,GRAY,false)); body.addView(space(20));\n        EditText email = edit("E-mail"); email.setInputType(InputType.TYPE_CLASS_TEXT | InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);\n        if(initialEmail!=null&&!initialEmail.isBlank()) email.setText(initialEmail);\n        body.addView(email,match(dp(58))); body.addView(space(12));\n        Button send = primary("Enviar link de recuperação"); body.addView(send,match(dp(58)));\n        back.setOnClickListener(v -> showLogin());\n        send.setOnClickListener(v -> recover(email.getText().toString().trim()));\n        setContentView(scroll(body,BLACK));\n    }\n\n    private void recover(String email) {\n        if(email.isBlank()){toast("Informe seu e-mail.");return;}\n        io.execute(() -> {\n            try {\n                JSONObject body = new JSONObject().put("email",email);\n                ApiClient.authPost("/auth/v1/recover?redirect_to=https%3A%2F%2Fclick-go-ten.vercel.app%2Fredefinir-senha",body);\n                ui.post(() -> new android.app.AlertDialog.Builder(this)\n                        .setTitle("Link enviado")\n                        .setMessage("Confira seu e-mail. Abra o link para criar uma nova senha e depois volte ao aplicativo.")\n                        .setPositiveButton("Voltar ao login",(d,w)->showLogin())\n                        .show());\n            } catch(Exception e){ui.post(()->toast(msg(e)));}\n        });\n    }\n'''
repl(old_login, new_login, 'login motorista')

# Libera mapa antigo ao reconstruir a home.
repl('''    private void showHome() {\n        LinearLayout root = vertical(BLACK); root.setPadding(dp(16),dp(18),dp(16),dp(20));\n''','''    private void showHome() {\n        releaseMap();\n        LinearLayout root = vertical(BLACK); root.setPadding(dp(16),dp(18),dp(16),dp(20));\n''','release home')

# Não acumula envios de GPS quando a rede demora.
repl('''        locationListener = loc -> { currentLocation=loc; if(online) io.execute(() -> { try { DriverRepository.updateLocation(token,loc.getLatitude(),loc.getLongitude(),loc.hasBearing()?loc.getBearing():null,loc.hasSpeed()?loc.getSpeed():null); } catch(Exception ignored){} }); };\n''','''        locationListener = loc -> {\n            currentLocation=loc;\n            if(online && sendingLocation.compareAndSet(false,true)) io.execute(() -> {\n                try { DriverRepository.updateLocation(token,loc.getLatitude(),loc.getLongitude(),loc.hasBearing()?loc.getBearing():null,loc.hasSpeed()?loc.getSpeed():null); }\n                catch(Exception ignored){}\n                finally { sendingLocation.set(false); }\n            });\n        };\n''','GPS sem fila')

# Não sobrepõe vários pollings simultâneos.
repl('''    private void refreshOperation(){ io.execute(() -> { try { JSONObject ride=DriverRepository.activeRide(token,userId); if(ride!=null){ui.post(()->renderRide(ride));return;} JSONObject offer=DriverRepository.firstOffer(token);ui.post(()->renderOffer(offer)); } catch(Exception e){ui.post(()->{if(operationTitle!=null)operationTitle.setText("Falha ao atualizar chamadas.");});} }); }\n''','''    private void refreshOperation(){\n        if(!refreshingOperation.compareAndSet(false,true)) return;\n        io.execute(() -> {\n            try {\n                JSONObject ride=DriverRepository.activeRide(token,userId);\n                if(ride!=null){ui.post(()->renderRide(ride));return;}\n                JSONObject offer=DriverRepository.firstOffer(token);\n                ui.post(()->renderOffer(offer));\n            } catch(Exception e){\n                ui.post(()->{if(operationTitle!=null)operationTitle.setText("Falha ao atualizar chamadas.");});\n            } finally {\n                refreshingOperation.set(false);\n            }\n        });\n    }\n''','polling sem fila')

# Lifecycle correto do mapa.
repl('''    @Override protected void onDestroy() {\n        destroyed = true; stopPolling(); stopLocationWatch(); io.shutdownNow();\n        if (map != null) map.onDetach();\n        super.onDestroy();\n    }\n''','''    @Override protected void onResume() { super.onResume(); if(map!=null) try{map.onResume();}catch(Exception ignored){} }\n    @Override protected void onPause() { if(map!=null) try{map.onPause();}catch(Exception ignored){} super.onPause(); }\n    @Override protected void onDestroy() {\n        destroyed = true; stopPolling(); stopLocationWatch(); releaseMap(); io.shutdownNow();\n        super.onDestroy();\n    }\n''','map lifecycle')

# Método releaseMap antes do logout.
repl('''    private void logout(){token=null;userId=null;online=false;getPreferences(MODE_PRIVATE).edit().clear().apply();stopPolling();stopLocationWatch();showLogin();}\n''','''    private void releaseMap(){MapView old=map;map=null;if(old!=null){try{old.onPause();}catch(Exception ignored){}try{old.onDetach();}catch(Exception ignored){}}}\n    private void logout(){token=null;userId=null;online=false;getPreferences(MODE_PRIVATE).edit().clear().apply();stopPolling();stopLocationWatch();releaseMap();showLogin();}\n''','release map method')

build_path = Path('app/build.gradle')
build = build_path.read_text(encoding='utf-8')
build = build.replace('versionCode 1','versionCode 2',1)
build = build.replace("versionName '0.1-native-beta'","versionName '0.2-native-beta'",1)
build_path.write_text(build,encoding='utf-8')

path.write_text(text,encoding='utf-8')
print('Motorista v0.2: olho, recuperação e estabilidade aplicados.')
